class Solution {
public:
    int minimumSumSubarray(vector<int>& nums, int l, int r) {
        int n = nums.size();
        int minPos = INT_MAX;
        for (int len = l; len <= r; ++len) {
            if (len > n) break;
            int currSum = 0;
            for (int i = 0; i < len; ++i) currSum += nums[i];
            if (currSum > 0) minPos = min(minPos, currSum);
            for (int i = len; i < n; ++i) {
                currSum += nums[i] - nums[i - len];
                if (currSum > 0) minPos = min(minPos, currSum);
            }
        }
        return minPos == INT_MAX ? -1 : minPos;
    }
};

class Solution {
    public int minimumSumSubarray(List<Integer> nums, int l, int r) {
        int n = nums.size();
        int minPos = Integer.MAX_VALUE;
        for (int len = l; len <= r; ++len) {
            if (len > n) break;
            int currSum = 0;
            for (int i = 0; i < len; ++i) currSum += nums.get(i);
            if (currSum > 0) minPos = Math.min(minPos, currSum);
            for (int i = len; i < n; ++i) {
                currSum += nums.get(i) - nums.get(i - len);
                if (currSum > 0) minPos = Math.min(minPos, currSum);
            }
        }
        return minPos == Integer.MAX_VALUE ? -1 : minPos;
    }
}

